"""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.
"""

from __future__ import annotations

import ast
import operator

from plugins import BUILTIN_PLUGINS


_BINARY_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.LShift: operator.lshift,
    ast.RShift: operator.rshift,
    ast.BitOr: operator.or_,
    ast.BitXor: operator.xor,
    ast.BitAnd: operator.and_,
}
_UNARY_OPERATORS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
    ast.Invert: operator.invert,
}
_COMPARISONS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.In: lambda left, right: left in right,
    ast.NotIn: lambda left, right: left not in right,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
}


def _evaluate(expression: str):
    """Evaluate the non-executable subset of expressions accepted in profiles."""
    root = ast.parse(expression, mode="eval")
    if sum(1 for _ in ast.walk(root)) > 1_000:
        raise ValueError("profile expression is too complex")

    def evaluate(node, names=None):
        names = {} if names is None else names
        if isinstance(node, ast.Constant):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in names:
                return names[node.id]
            raise ValueError(f"unknown name in profile expression: {node.id}")
        if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            values = [evaluate(item, names) for item in node.elts]
            return {ast.List: list, ast.Tuple: tuple, ast.Set: set}[type(node)](values)
        if isinstance(node, ast.Dict):
            if any(key is None for key in node.keys):
                raise ValueError("dictionary unpacking is not allowed")
            return {
                evaluate(key, names): evaluate(value, names)
                for key, value in zip(node.keys, node.values)
            }
        if isinstance(node, ast.BinOp) and type(node.op) in _BINARY_OPERATORS:
            return _BINARY_OPERATORS[type(node.op)](
                evaluate(node.left, names), evaluate(node.right, names)
            )
        if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY_OPERATORS:
            return _UNARY_OPERATORS[type(node.op)](evaluate(node.operand, names))
        if isinstance(node, ast.BoolOp):
            values = node.values
            result = evaluate(values[0], names)
            for value in values[1:]:
                if isinstance(node.op, ast.And) and not result:
                    break
                if isinstance(node.op, ast.Or) and result:
                    break
                result = evaluate(value, names)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, names)
            for op, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator, names)
                operation = _COMPARISONS.get(type(op))
                if operation is None or not operation(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.IfExp):
            branch = node.body if evaluate(node.test, names) else node.orelse
            return evaluate(branch, names)
        if isinstance(node, ast.Subscript):
            return evaluate(node.value, names)[evaluate(node.slice, names)]
        if isinstance(node, ast.Slice):
            return slice(
                evaluate(node.lower, names) if node.lower else None,
                evaluate(node.upper, names) if node.upper else None,
                evaluate(node.step, names) if node.step else None,
            )
        if isinstance(node, (ast.ListComp, ast.SetComp, ast.DictComp)):
            results = []

            def visit_generator(index, scope):
                if index == len(node.generators):
                    if isinstance(node, ast.DictComp):
                        results.append((evaluate(node.key, scope), evaluate(node.value, scope)))
                    else:
                        results.append(evaluate(node.elt, scope))
                    if len(results) > 10_000:
                        raise ValueError("profile comprehension is too large")
                    return
                generator = node.generators[index]
                if generator.is_async or not isinstance(generator.target, ast.Name):
                    raise ValueError("unsupported profile comprehension")
                iterable = evaluate(generator.iter, scope)
                for item in iterable:
                    child_scope = dict(scope)
                    child_scope[generator.target.id] = item
                    if all(evaluate(condition, child_scope) for condition in generator.ifs):
                        visit_generator(index + 1, child_scope)

            visit_generator(0, names)
            if isinstance(node, ast.DictComp):
                return dict(results)
            return set(results) if isinstance(node, ast.SetComp) else results
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "range"
            and not node.keywords
        ):
            arguments = [evaluate(argument, names) for argument in node.args]
            value = range(*arguments)
            if len(value) > 10_000:
                raise ValueError("profile range is too large")
            return value
        raise ValueError(f"unsupported profile expression: {type(node).__name__}")

    return evaluate(root.body)


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name (an instance,
    or ``None`` when the profile sets no plugin).
    """
    settings = {}
    plugin_name = None

    for line_number, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError(f"invalid profile line {line_number}: expected key = value")
        key, expression = (part.strip() for part in line.split("=", 1))
        if not key or not expression:
            raise ValueError(f"invalid profile line {line_number}: expected key = value")
        try:
            value = _evaluate(expression)
        except (SyntaxError, TypeError, ValueError, ZeroDivisionError, OverflowError) as error:
            raise ValueError(f"invalid value on profile line {line_number}: {error}") from error
        if key == "plugin":
            plugin_name = value
        else:
            settings[key] = value

    if plugin_name is None:
        plugin = None
    else:
        if not isinstance(plugin_name, str):
            raise ValueError("plugin name must be a string")
        try:
            plugin_class = BUILTIN_PLUGINS[plugin_name]
        except KeyError as error:
            raise ValueError(f"unknown transform plugin: {plugin_name}") from error
        plugin = plugin_class()

    return {"settings": settings, "plugin": plugin}
